     6	import java.math.BigDecimal;
     7	import java.time.format.DateTimeFormatter;
     8	
     9	public class ComprovanteGenerator implements DocumentGenerator {
    10	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    11	
    12	    @Override
    13	    public String generate(Reservation reservation) {
    14	        StringBuilder sb = new StringBuilder();
    15	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    16	
    17	        CpfIdentification cpf = (CpfIdentification) reservation.getIdentification();
    18	        sb.append("Hóspede: ").append(reservation.getGuestName())
    19	          .append(" (CPF ").append(formatCpf(cpf.cpf())).append(")\n");
    20	
    21	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    22	          .append(" (").append(reservation.getRoomType()).append(")\n");
    23	
    24	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT))
    25	          .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT))
    26	          .append(" | ").append(reservation.getNights())
    27	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    28	
    29	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    30	
    31	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    32	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    33	        }
    34	
    35	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
    36	
    37	        return sb.toString();
    38	    }
    39	
    40	    private String formatCpf(String cpf) {
    41	        if (cpf.length() == 11) {
    42	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    43	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    44	        }
    45	        return cpf;
    46	    }
    47	
    48	    private String formatMoney(BigDecimal amount) {
    49	        return String.format(java.util.Locale.of("pt", "BR"), "R$ %,.2f", amount);
    50	    }
    51	}
