     1	package com.pousada.document;
     2	
     3	import com.pousada.domain.CnpjIdentification;
     4	import com.pousada.domain.Reservation;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.format.DateTimeFormatter;
     9	
    10	public class FaturaGenerator implements DocumentGenerator {
    11	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    13	
    14	    @Override
    15	    public String generate(Reservation reservation) {
    16	        StringBuilder sb = new StringBuilder();
    17	        sb.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
    18	
    19	        CnpjIdentification cnpj = (CnpjIdentification) reservation.getIdentification();
    20	        sb.append("Empresa: ").append(cnpj.companyName())
    21	          .append(" (CNPJ ").append(formatCnpj(cnpj.cnpj())).append(")\n");
    22	
    23	        sb.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
    24	
    25	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    26	          .append(" (").append(reservation.getRoomType()).append(")\n");
    27	
    28	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT))
    29	          .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT))
    30	          .append(" | ").append(reservation.getNights())
    31	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    32	
    33	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    34	
    35	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    36	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    37	        }
    38	
    39	        sb.append("Total: ").append(formatMoney(reservation.getTotal())).append("\n");
    40	
    41	        BigDecimal iss = reservation.getTotal().multiply(ISS_RATE)
    42	            .setScale(2, RoundingMode.HALF_EVEN);
    43	        sb.append("ISS retido (5%): ").append(formatMoney(iss));
    44	
    45	        return sb.toString();
    46	    }
    47	
    48	    private String formatCnpj(String cnpj) {
    49	        if (cnpj.length() == 14) {
    50	            return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
    51	                   cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
    52	        }
    53	        return cnpj;
    54	    }
    55	
    56	    private String formatMoney(BigDecimal amount) {
    57	        return String.format(java.util.Locale.of("pt", "BR"), "R$ %,.2f", amount);
    58	    }
    59	}
