     1	package com.pousada.document;
     2	
     3	import com.pousada.domain.PassportIdentification;
     4	import com.pousada.domain.Reservation;
     5	
     6	import java.math.BigDecimal;
     7	import java.text.DecimalFormat;
     8	import java.text.DecimalFormatSymbols;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.Locale;
    11	
    12	public class ReceiptGenerator implements DocumentGenerator {
    13	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    14	
    15	    @Override
    16	    public String generate(Reservation reservation) {
    17	        StringBuilder sb = new StringBuilder();
    18	        sb.append("Booking receipt no. ").append(reservation.getId()).append("\n");
    19	
    20	        PassportIdentification passport = (PassportIdentification) reservation.getIdentification();
    21	        sb.append("Guest: ").append(reservation.getGuestName())
    22	          .append(" (passport ").append(passport.passport())
    23	          .append(", ").append(passport.country()).append(")\n");
    24	
    25	        sb.append("Room: ").append(reservation.getRoomNumber())
    26	          .append(" (").append(reservation.getRoomType()).append(")\n");
    27	
    28	        sb.append("Check-in: ").append(reservation.getCheckIn().format(DATE_FORMAT))
    29	          .append(" | Check-out: ").append(reservation.getCheckOut().format(DATE_FORMAT))
    30	          .append(" | ").append(reservation.getNights())
    31	          .append(reservation.getNights() == 1 ? " night" : " nights").append("\n");
    32	
    33	        sb.append("Nights: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    34	
    35	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    36	            sb.append("Discount: ").append(formatMoney(reservation.getDiscount())).append("\n");
    37	        }
    38	
    39	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
    40	
    41	        return sb.toString();
    42	    }
    43	
    44	    private String formatMoney(BigDecimal amount) {
    45	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
    46	        symbols.setGroupingSeparator(',');
    47	        symbols.setDecimalSeparator('.');
    48	        DecimalFormat df = new DecimalFormat("BRL #,##0.00", symbols);
    49	        return df.format(amount);
    50	    }
    51	}
