     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.Message;
     4	import com.pousada.domain.Reservation;
     5	import com.pousada.repository.MessageRepository;
     6	
     7	public class EmailService {
     8	    private final MessageRepository messageRepository;
     9	    private final DocumentService documentService;
    10	
    11	    public EmailService(MessageRepository messageRepository, DocumentService documentService) {
    12	        this.messageRepository = messageRepository;
    13	        this.documentService = documentService;
    14	    }
    15	
    16	    public void sendConfirmationEmail(Reservation reservation) {
    17	        String document = documentService.generateDocument(reservation);
    18	
    19	        String body = String.format(
    20	            "Olá, %s!\n\n" +
    21	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
    22	            "%s\n\n" +
    23	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
    24	            "Até breve!",
    25	            reservation.getGuestName(),
    26	            document
    27	        );
    28	
    29	        long id = messageRepository.nextId();
    30	        Message message = new Message(
    31	            id,
    32	            "EMAIL",
    33	            reservation.getGuestEmail(),
    34	            "Reserva confirmada - Pousada Maré Alta",
    35	            body
    36	        );
    37	
    38	        messageRepository.save(message);
    39	    }
    40	
    41	    public java.util.List<Message> getAllMessages() {
    42	        return messageRepository.findAll();
    43	    }
    44	}

