    10	
    11	public class ReservationService {
    12	    private final ReservationRepository reservationRepository;
    13	    private final RoomRepository roomRepository;
    14	    private final EmailService emailService;
    15	
    16	    public ReservationService(ReservationRepository reservationRepository,
    17	                             RoomRepository roomRepository,
    18	                             EmailService emailService) {
    19	        this.reservationRepository = reservationRepository;
    20	        this.roomRepository = roomRepository;
    21	        this.emailService = emailService;
    22	    }
    23	
    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        GuestIdentification identification, LocalDate checkIn,
    26	                                        LocalDate checkOut, int guests, RatePlan ratePlan) {
    27	
    28	        Room room = roomRepository.findByNumber(roomNumber)
    29	            .orElseThrow(() -> new RoomNotFoundException());
    30	
    31	        if (guests > room.getCapacity()) {
    32	            throw new CapacityExceededException();
    33	        }
    34	
    35	        if (guests < 1) {
    36	            throw new InvalidRequestException();
    37	        }
    38	
    39	        if (!reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut).isEmpty()) {
    40	            throw new RoomUnavailableException();
    41	        }
    42	
    43	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    44	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    45	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    46	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    47	
    48	        long id = reservationRepository.nextId();
    49	        Reservation reservation = new Reservation(
    50	            id, roomNumber, room.getType(), guestName, guestEmail, identification,
    51	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total
    52	        );
    53	
    54	        return reservationRepository.save(reservation);
    55	    }
    56	
    57	    public Reservation confirmReservation(long id) {
    58	        Reservation reservation = reservationRepository.findById(id)
    59	            .orElseThrow(() -> new ReservationNotFoundException());
    60	
    61	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    62	            throw new OperationNotAllowedException();
    63	        }
    64	
    65	        reservation.setStatus(ReservationStatus.CONFIRMED);
    66	        reservation.setAmountPaid(reservation.getTotal());
    67	
    68	        emailService.sendConfirmationEmail(reservation);
    69	
    70	        return reservation;
    71	    }
    72	
    73	    public Reservation cancelReservation(long id) {
    74	        Reservation reservation = reservationRepository.findById(id)
    75	            .orElseThrow(() -> new ReservationNotFoundException());
    76	
    77	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
    78	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
    79	            reservation.getStatus() == ReservationStatus.CANCELLED) {
    80	            throw new OperationNotAllowedException();
    81	        }
    82	
    83	        reservation.setStatus(ReservationStatus.CANCELLED);
    84	
    85	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
    86	            reservation.setRefund(reservation.getAmountPaid());
    87	        } else {
    88	            reservation.setRefund(BigDecimal.ZERO);
    89	        }
    90	
    91	        return reservation;
    92	    }
    93	
    94	    public Reservation checkIn(long id) {
    95	        Reservation reservation = reservationRepository.findById(id)
    96	            .orElseThrow(() -> new ReservationNotFoundException());
    97	
    98	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    99	            throw new OperationNotAllowedException();
   100	        }
   101	
   102	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   103	        return reservation;
   104	    }
   105	
   106	    public Reservation checkOut(long id) {
   107	        Reservation reservation = reservationRepository.findById(id)
   108	            .orElseThrow(() -> new ReservationNotFoundException());
   109	
   110	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   111	            throw new OperationNotAllowedException();
   112	        }
   113	
   114	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   115	        return reservation;
   116	    }
   117	
   118	    public Reservation getReservation(long id) {
   119	        return reservationRepository.findById(id)
   120	            .orElseThrow(() -> new ReservationNotFoundException());
   121	    }
