  3	import com.fasterxml.jackson.databind.DeserializationFeature;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.fasterxml.jackson.databind.SerializationFeature;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	import com.pousada.api.dto.*;
  8	import com.pousada.domain.*;
  9	import com.pousada.repository.MessageRepository;
 10	import com.pousada.repository.ReservationRepository;
 11	import com.pousada.repository.RoomRepository;
 12	import com.pousada.service.*;
 13	import io.javalin.Javalin;
 14	import io.javalin.http.Context;
 15	import io.javalin.json.JavalinJackson;
 16	
 17	import java.time.LocalDate;
 18	import java.time.format.DateTimeFormatter;
 19	import java.time.format.DateTimeParseException;
 20	
 21	public class Application {
 22	
 23	    public static void main(String[] args) {
 24	        RoomRepository roomRepository = new RoomRepository();
 25	        ReservationRepository reservationRepository = new ReservationRepository();
 26	        MessageRepository messageRepository = new MessageRepository();
 27	
 28	        DocumentService documentService = new DocumentService();
 29	        EmailService emailService = new EmailService(messageRepository, documentService);
 30	        ReservationService reservationService = new ReservationService(
 31	            reservationRepository, roomRepository, emailService
 32	        );
 33	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 34	
 35	        ObjectMapper objectMapper = new ObjectMapper()
 36	            .registerModule(new JavaTimeModule())
 37	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 38	            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
 39	
 40	        String portStr = System.getenv("PORT");
 41	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 42	
 43	        Javalin app = Javalin.create(config -> {
 44	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 45	        }).start(port);
 46	
 47	        app.get("/rooms", ctx -> {
 48	            var rooms = roomRepository.findAll().stream()
 49	                .map(r -> new RoomResponse(r.getNumber(), r.getType().name(), r.getCapacity(), r.getNightlyRate()))
 50	                .toList();
 51	            ctx.json(rooms);
 52	        });
 53	
 54	        app.post("/reservations", ctx -> {
 55	            try {
 56	                CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 57	
 58	                if (request.getRoomNumber() == null || request.getGuestName() == null ||
 59	                    request.getGuestEmail() == null || request.getCheckIn() == null ||
 60	                    request.getCheckOut() == null || request.getGuests() == null ||
 61	                    request.getRatePlan() == null) {
 62	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
 63	                    return;
 64	                }
 65	
 66	                if (request.getCheckOut().isBefore(request.getCheckIn()) ||
 67	                    request.getCheckOut().isEqual(request.getCheckIn())) {
 68	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
 69	                    return;
 70	                }
 71	
 72	                GuestIdentification identification = parseIdentification(request);
 73	                if (identification == null) {
 74	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid guest identification"));
 75	                    return;
 76	                }
 77	
 78	                RatePlan ratePlan;
 79	                try {
 80	                    ratePlan = RatePlan.valueOf(request.getRatePlan());
 81	                } catch (IllegalArgumentException e) {
 82	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
 83	                    return;
 84	                }
 85	
 86	                Reservation reservation = reservationService.createReservation(
 87	                    request.getRoomNumber(),
 88	                    request.getGuestName(),
 89	                    request.getGuestEmail(),
 90	                    identification,
 91	                    request.getCheckIn(),
 92	                    request.getCheckOut(),
 93	                    request.getGuests(),
 94	                    ratePlan
 95	                );
 96	
 97	                ctx.status(201).json(ReservationResponse.from(reservation));
 98	
 99	            } catch (ReservationService.RoomNotFoundException e) {
100	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
101	            } catch (ReservationService.CapacityExceededException e) {
102	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
103	            } catch (ReservationService.RoomUnavailableException e) {
104	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
105	            } catch (ReservationService.InvalidRequestException e) {
106	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
107	            } catch (Exception e) {
108	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request: " + e.getMessage()));
109	            }
110	        });
111	
112	        app.get("/reservations/{id}", ctx -> {
113	            try {
114	                long id = Long.parseLong(ctx.pathParam("id"));
115	                Reservation reservation = reservationService.getReservation(id);
116	                ctx.json(ReservationResponse.from(reservation));
117	            } catch (ReservationService.ReservationNotFoundException e) {
118	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
119	            } catch (NumberFormatException e) {
120	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
121	            }
122	        });
123	
124	        app.post("/reservations/{id}/confirmation", ctx -> {
125	            try {
126	                long id = Long.parseLong(ctx.pathParam("id"));
127	                Reservation reservation = reservationService.confirmReservation(id);
128	                ctx.json(ReservationResponse.from(reservation));
129	            } catch (ReservationService.ReservationNotFoundException e) {
130	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
131	            } catch (ReservationService.OperationNotAllowedException e) {
132	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current state"));
133	            } catch (NumberFormatException e) {
134	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
135	            }
136	        });
137	
138	        app.post("/reservations/{id}/cancellation", ctx -> {
139	            try {
140	                long id = Long.parseLong(ctx.pathParam("id"));
141	                Reservation reservation = reservationService.cancelReservation(id);
142	                ctx.json(ReservationResponse.from(reservation));
143	            } catch (ReservationService.ReservationNotFoundException e) {
144	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
145	            } catch (ReservationService.OperationNotAllowedException e) {
146	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current state"));
147	            } catch (NumberFormatException e) {
148	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
149	            }
150	        });
151	
152	        app.post("/reservations/{id}/check-in", ctx -> {
153	            try {
154	                long id = Long.parseLong(ctx.pathParam("id"));
155	                Reservation reservation = reservationService.checkIn(id);
156	                ctx.json(ReservationResponse.from(reservation));
157	            } catch (ReservationService.ReservationNotFoundException e) {
158	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
159	            } catch (ReservationService.OperationNotAllowedException e) {
160	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current state"));
161	            } catch (NumberFormatException e) {
162	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
163	            }
164	        });
165	
166	        app.post("/reservations/{id}/check-out", ctx -> {
167	            try {
168	                long id = Long.parseLong(ctx.pathParam("id"));
169	                Reservation reservation = reservationService.checkOut(id);
170	                String documentText = documentService.generateDocument(reservation);
171	                ctx.json(DocumentResponse.from(reservation, documentText));
172	            } catch (ReservationService.ReservationNotFoundException e) {
173	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
174	            } catch (ReservationService.OperationNotAllowedException e) {
175	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current state"));
176	            } catch (NumberFormatException e) {
177	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
178	            }
179	        });
180	
181	        app.get("/reservations/{id}/document", ctx -> {
182	            try {
183	                long id = Long.parseLong(ctx.pathParam("id"));
184	                Reservation reservation = reservationService.getReservation(id);
185	
186	                if (reservation.getStatus() == ReservationStatus.PENDING) {
187	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document not available for pending reservations"));
188	                    return;
189	                }
190	
191	                String documentText = documentService.generateDocument(reservation);
192	                ctx.json(DocumentResponse.from(reservation, documentText));
193	            } catch (ReservationService.ReservationNotFoundException e) {
194	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
195	            } catch (NumberFormatException e) {
196	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
197	            }
198	        });
199	
200	        app.get("/messages", ctx -> {
201	            var messages = emailService.getAllMessages().stream()
202	                .map(MessageResponse::from)
203	                .toList();
204	            ctx.json(messages);
205	        });
206	
207	        app.get("/reports/occupancy", ctx -> {
208	            try {
209	                String dateStr = ctx.queryParam("date");
210	                if (dateStr == null) {
211	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
212	                    return;
213	                }
214	
215	                LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
216	                String csv = reportService.generateOccupancyReport(date);
217	                ctx.contentType("text/csv; charset=utf-8").result(csv);
218	            } catch (DateTimeParseException e) {
219	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
220	            }
221	        });
222	
223	        app.get("/reports/revenue", ctx -> {
224	            try {
225	                String monthStr = ctx.queryParam("month");
226	                if (monthStr == null) {
227	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
228	                    return;
229	                }
230	
231	                String[] parts = monthStr.split("-");
232	                if (parts.length != 2) {
233	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
234	                    return;
235	                }
236	
237	                int year = Integer.parseInt(parts[0]);
238	                int month = Integer.parseInt(parts[1]);
239	
240	                if (month < 1 || month > 12) {
241	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month"));
242	                    return;
243	                }
244	
245	                String csv = reportService.generateRevenueReport(year, month);
246	                ctx.contentType("text/csv; charset=utf-8").result(csv);
247	            } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
248	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
249	            }
250	        });
251	    }
252	
253	    private static GuestIdentification parseIdentification(CreateReservationRequest request) {
254	        int count = 0;
255	        GuestIdentification result = null;
256	
257	        if (request.getGuestCpf() != null) {
258	            count++;
259	            result = new CpfIdentification(request.getGuestCpf());
260	        }
261	
262	        if (request.getCompanyCnpj() != null && request.getCompanyName() != null) {
263	            count++;
264	            result = new CnpjIdentification(request.getCompanyCnpj(), request.getCompanyName());
265	        } else if (request.getCompanyCnpj() != null || request.getCompanyName() != null) {
266	            return null;
267	        }
268	
269	        if (request.getGuestPassport() != null && request.getGuestCountry() != null) {
270	            count++;
271	            result = new PassportIdentification(request.getGuestPassport(), request.getGuestCountry());
272	        } else if (request.getGuestPassport() != null || request.getGuestCountry() != null) {
273	            return null;
274	        }
275	
276	        return count == 1 ? result : null;
277	    }
278	}

