220	            }
221	        });
222	
223	        app.get("/reports/revenue", ctx -> {
224	            try {
225	                String monthStr = ctx.queryParam("month");
226	                if (monthStr == null) {
227	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
228	                    return;
229	                }
230	
231	                String[] parts = monthStr.split("-");
232	                if (parts.length != 2) {
233	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
234	                    return;
235	                }
236	
237	                int year = Integer.parseInt(parts[0]);
238	                int month = Integer.parseInt(parts[1]);
239	
240	                if (month < 1 || month > 12) {
241	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month"));
242	                    return;
243	                }
244	
245	                String csv = reportService.generateRevenueReport(year, month);
246	                ctx.contentType("text/csv; charset=utf-8").result(csv);
247	            } catch (NumberFormatException | ArrayIndexOutOfBoundsException e) {
248	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
249	            }
250	        });
251	    }
