280	import com.pousada.domain.RatePlan;
281	
282	import java.math.BigDecimal;
283	import java.math.RoundingMode;
284	import java.time.LocalDate;
285	
286	public class PriceCalculator {
287	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
288	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
289	
290	    public static boolean isHighSeason(LocalDate date) {
291	        int month = date.getMonthValue();
292	        int day = date.getDayOfMonth();
293	
294	        if (month == 7) {
295	            return true;
296	        }
297	
298	        if (month == 12 && day >= 15) {
299	            return true;
300	        }
301	
302	        if (month == 1 || month == 2) {
303	            return true;
304	        }
305	
306	        return false;
307	    }
308	
309	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
310	        BigDecimal price = baseRate;
311	        if (isHighSeason(night)) {
312	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
313	        }
314	        return price.setScale(2, RoundingMode.HALF_EVEN);
315	    }
316	
317	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
318	        BigDecimal subtotal = BigDecimal.ZERO;
319	        LocalDate current = checkIn;
320	
321	        while (current.isBefore(checkOut)) {
322	            subtotal = subtotal.add(calculateNightPrice(baseRate, current));
323	            current = current.plusDays(1);
324	        }
325	
326	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
327	    }
328	
329	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
330	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
331	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
332	                .setScale(2, RoundingMode.HALF_EVEN);
333	        }
334	        return BigDecimal.ZERO;
335	    }
336	
337	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
338	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
339	    }
340	}

